(* [comment removed for export] *)
Theorem bc_tap_full : forall k s n sp rg bv,
  bc_avg k s n -> 0 <= k -> k + 1 <= 2048 -> FB fmt_single 1 sp -> FB fmt_single 1 rg -> 0 <= bv <= 255 ->
  let kern := fst (fp_mul fmt_single RNE sp rg) in
  let b := fst (fp_of_int fmt_single RNE false 32 bv) in
  let n' := fst (fp_add fmt_single RNE n kern) in
  let s' := fst (fp_fma fmt_single RNE kern b s) in
  bc_avg (k + 1) s' n' /\ 0 <= sp < 2 ^ 32 /\ 0 <= rg < 2 ^ 32 /\ 0 <= kern < 2 ^ 32 /\ 0 <= b < 2 ^ 32 /\ 0 <= s' < 2 ^ 32 /\ 0 <= n' < 2 ^ 32.
