Theorem bc_kfract_full : forall xi xa xb i a b,
  bc_int xi i -> bc_int xa a -> bc_int xb b -> a <= i < b -> b <= 255 ->
  let d := fst (fp_sub fmt_single RNE xb xa) in
  let e := fst (fp_sub fmt_single RNE xi xa) in
  let c := fst (fp_div fmt_single RNE e d) in
